"""Topic rules for school Grades 6-10 (and useful at College Level 1-2): simple
stories, a few formulas students actually use, and a few kid-friendly charts."""
from . import F, Tab, Case, Chart, Rule

ALL = ["6", "7", "8", "9", "10", "c1", "c2"]
UP8 = ["8", "9", "10", "c1", "c2"]
UP9 = ["9", "10", "c1", "c2"]
SCI = ["Science", "Biology", "Physics", "Chemistry"]


def ev(rid, pattern, title, when, summary, takeaway, wiki, subjects=None, levels=ALL, formulas=(), tables=(), charts=()):
    return Rule(rid, pattern, "", subjects, formulas=list(formulas), tables=list(tables), charts=list(charts),
                cases=[Case(title, when, summary, takeaway, wiki)] if title else [], levels=levels)


def only(rid, pattern, subjects=None, levels=ALL, formulas=(), tables=(), charts=()):
    return Rule(rid, pattern, "", subjects, formulas=list(formulas), tables=list(tables), charts=list(charts), levels=levels)


