ev("k_greece", r"Ancient Greece|Greek City|Olympic", "The first Olympic Games", "776 BCE (traditional date)", "The ancient Greeks held athletic contests at Olympia every four years in honour of Zeus; wars were paused so athletes could travel safely.", "Sport can bring people together.", "Ancient Olympic Games", ["World History", "Physical Education & Self-Defense", "General Knowledge"], ALL),
