ev("k_hands", r"Handwashing|Hand Hygiene|Personal Hygiene|Food Hygiene|Kitchen Safety and Hygiene", "Semmelweis and handwashing", "1847", "Dr Ignaz Semmelweis asked doctors in a Vienna hospital to wash their hands in chlorinated lime, and deaths of mothers after childbirth fell from roughly 10% to about 2%.", "Clean hands save lives.", "Ignaz Semmelweis", ["Health Education", "First Aid", "Cooking", "Biology"], ALL),
ev("k_smoking", r"Tobacco|Smoking|Substance", "Smoking and lung cancer", "1950–1954", "Richard Doll and Austin Bradford Hill followed tens of thousands of British doctors and found that smokers were far more likely to die of lung cancer.", "Large studies show cause and risk.", "Richard Doll", ["Health Education", "Biology", "Social Studies"], ALL),
ev("k_beep", r"Fitness Testing|Beep Test", "The beep test", "1982", "Luc Léger designed the multistage fitness test, in which runners keep pace with beeps that get faster, to estimate aerobic fitness.", "Fitness can be measured.", "Beep test", ["Physical Education & Self-Defense", "Health Education"], ALL),
ev("k_perspective", r"Perspective Drawing|Linear Perspective|One-Point|Two-Point|Shading and Perspective", "Brunelleschi's perspective", "c. 1415", "Florentine architect Filippo Brunelleschi showed how to draw buildings so that parallel lines meet at a vanishing point, and Masaccio used it in his Holy Trinity fresco around 1427.", "Mathematics helped artists create depth.", "Linear perspective", ["Art", "Art History", "Math"], ALL),
ev("k_alphabet", r"Alphabet|Writing Systems?|Urdu Script|Arabic Script|Cyrillic|Script and (Pronunciation|Writing)", "The Phoenician alphabet", "c. 1050 BCE", "Phoenician traders used 22 letters for consonant sounds; the Greeks added vowels, and the Latin alphabet used in English developed from it.", "One simple writing system spread across the world.", "Phoenician alphabet", ["Foreign Languages", "English", "World History", "Islamic Studies"], ALL),
